import base64,hashlib,json
from pathlib import Path
assert b'RUNPOD_POD_ID=z4vt4pqlra2qop' in Path('/proc/1/environ').read_bytes().split(b'\0')
payload=base64.b64decode('')
target=Path('/workspace/quality-control/runs/pr32-validation/probe_cloud_quality_attempts_v10.py')
if target.exists():assert target.read_bytes()==payload
else:target.write_bytes(payload)
assert hashlib.sha256(target.read_bytes()).hexdigest()=='b5eb753610ff2dee4aabab733fd9d740d7540f2c3d5fae5e57ce550b39c1978b'
print(json.dumps({'path':str(target),'sha256':hashlib.sha256(payload).hexdigest()}))
